let gameMode=loadPlayMode(),score=0,best=0,runBest=0,energy=100,aim=250,cooldown=0,paused=false,ended=false,muted=loadSoundPreference(),audio=null,audioUnlocked=false,masterGain=null,sfxGain=null,musicGain=null,musicTimer=0,musicStep=0,musicDucked=false,loaded=false,hasWon=false,toastUntil=0,heldTilt=0,combo=0,lastMerge=-Infinity,heat=0,heatUntil=0,heatBursts=0;
