let launchState={levelId:1,seed:launchSeed,score:0,best:0,ammo:8,maxAmmo:8,stability:100,combo:0,maxCombo:0,shotState:'ready',activeProjectile:null,fruitQueue:[],goals:[],completedGoals:0,failedShots:0,specialHits:0,rating:null,ended:false,pendingComplete:false,shotScored:0,aim:{active:false,pointerId:null,angle:0,force:0,velocity:{x:0,y:0},predictedPoint:null,warning:null},lastShot:{fruitType:null,targets:[],chain:0,score:0,hazards:0,perfect:false,reason:null},failure:{reason:null,protectionAvailable:true,protectionUsed:false},ghost:{current:[],best:null,playing:false},shotId:0,shotEvents:[],shotHistory:[],currentShot:null};

