function createRng(value){let state=(value>>>0)||1;return()=>{state=(Math.imul(state,1664525)+1013904223)>>>0;return state/4294967296;};}
function newSeed(){return ((Date.now()^Math.floor(Math.random()*0xffffffff))>>>0)||1;}
function loadPlayMode(){try{return localStorage.getItem(PLAY_MODE_KEY)==='classic'?'classic':'launch';}catch{return 'launch';}}
function savePlayMode(){try{localStorage.setItem(PLAY_MODE_KEY,gameMode);}catch{}}
function loadCodex(){const fallback={version:1,discovered:Array.from({length:TYPES.length},(_,i)=>i<2)};try{const parsed=JSON.parse(localStorage.getItem(CODEX_KEY)||'');if(parsed?.version!==1||!Array.isArray(parsed.discovered)||parsed.discovered.length!==TYPES.length||parsed.discovered.some(value=>typeof value!=='boolean'))return fallback;return {version:1,discovered:parsed.discovered.slice()};}catch{return fallback;}}
function saveCodex(){try{localStorage.setItem(CODEX_KEY,JSON.stringify(codex));}catch{}}
function loadLaunchProgress(){const fallback={version:1,unlockedLevel:1,completed:{},bestScores:{},bestRatings:{},bestShots:{},bestStability:{},ghosts:{},cosmetics:[],seedBest:{}};const isMap=value=>value&&typeof value==='object'&&!Array.isArray(value);try{const parsed=JSON.parse(localStorage.getItem(LAUNCH_KEY)||'');if(parsed?.version!==1||!isMap(parsed.completed)||!isMap(parsed.bestScores)||!isMap(parsed.bestRatings)||!Number.isInteger(parsed.unlockedLevel))return fallback;return {...fallback,...parsed,completed:parsed.completed,bestScores:parsed.bestScores,bestRatings:parsed.bestRatings,bestShots:isMap(parsed.bestShots)?parsed.bestShots:{},bestStability:isMap(parsed.bestStability)?parsed.bestStability:{},ghosts:isMap(parsed.ghosts)?parsed.ghosts:{},cosmetics:Array.isArray(parsed.cosmetics)?parsed.cosmetics:[],seedBest:isMap(parsed.seedBest)?parsed.seedBest:{},unlockedLevel:Math.max(1,Math.min(LAUNCH_LEVELS.length,parsed.unlockedLevel))};}catch{return fallback;}}
function saveLaunchProgress(){try{localStorage.setItem(LAUNCH_KEY,JSON.stringify(launchProgress));}catch{}}
function loadSoundPreference(){try{return localStorage.getItem(SOUND_KEY)!=='on';}catch{return true;}}
function syncSoundUI(){const button=$('sound');if(!button)return;button.setAttribute('aria-pressed',String(!muted));button.setAttribute('aria-label',muted?'开启声音':'静音');button.querySelector('span').textContent=muted?'声音':'静音';}
function ensureAudio(){if(audio)return audio;try{const AudioCtor=window.AudioContext||window.webkitAudioContext;if(!AudioCtor)return null;audio=new AudioCtor();masterGain=audio.createGain();sfxGain=audio.createGain();musicGain=audio.createGain();masterGain.gain.value=.64;sfxGain.gain.value=.72;musicGain.gain.value=musicDucked?.025:.08;const compressor=audio.createDynamicsCompressor();compressor.threshold.value=-20;compressor.knee.value=18;compressor.ratio.value=5;compressor.attack.value=.008;compressor.release.value=.22;sfxGain.connect(masterGain);musicGain.connect(masterGain);masterGain.connect(compressor).connect(audio.destination);audioUnlocked=true;return audio;}catch{return null;}}
function unlockAudio(){if(muted)return null;const context=ensureAudio();if(!context)return null;if(context.state==='suspended')context.resume().catch(()=>{});if(!musicTimer)startMusic();return context;}
function scheduleSfxTone(context,frequency,when,length=.1,options={}){const oscillator=context.createOscillator(),gain=context.createGain(),volume=options.volume??.08,start=Math.max(when,context.currentTime+.001),end=start+length;oscillator.type=options.type||'sine';oscillator.frequency.setValueAtTime(Math.max(20,frequency),start);if(options.endFrequency)oscillator.frequency.exponentialRampToValueAtTime(Math.max(20,options.endFrequency),end);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(Math.max(.0001,volume),start+Math.min(.025,length*.25));gain.gain.exponentialRampToValueAtTime(.0001,end);oscillator.connect(gain).connect(sfxGain);oscillator.start(start);oscillator.stop(end+.02);}
function playSfx(name,detail={}){if(muted)return;const context=unlockAudio();if(!context||!sfxGain)return;const now=context.currentTime+.008,note=(frequency,offset=0,length=.1,options={})=>scheduleSfxTone(context,frequency,now+offset,length,options);const type=detail.type||0,chain=Math.min(4,Math.max(1,detail.chain||1));switch(name){case'tone':note(detail.frequency||420,0,detail.length||.09,{type:'sine',volume:.06,endFrequency:(detail.frequency||420)*.55});break;case'drop':note(220,0,.07,{type:'triangle',volume:.045,endFrequency:310});note(330,.045,.1,{type:'sine',volume:.035,endFrequency:380});break;case'merge':{const base=300+type*42+chain*18;note(base,0,.13,{type:'sine',volume:.07,endFrequency:base*1.18});if(detail.cascade||detail.perfect)note(base*1.5,.06,.18,{type:'triangle',volume:.045,endFrequency:base*1.9});if(chain>=3)note(base*2,.12,.22,{type:'sine',volume:.035});break;}case'stir':note(180,0,.18,{type:'sine',volume:.05,endFrequency:360});note(280,.08,.24,{type:'triangle',volume:.035,endFrequency:520});break;case'mission':note(520,0,.16,{type:'sine',volume:.055});note(660,.11,.18,{type:'sine',volume:.05});note(780,.22,.26,{type:'triangle',volume:.04});break;case'ability':note(340,0,.16,{type:'triangle',volume:.05,endFrequency:520});note(520,.12,.2,{type:'sine',volume:.045,endFrequency:780});break;case'vent':note(190,0,.3,{type:'sawtooth',volume:.045,endFrequency:90});note(120,.12,.35,{type:'sine',volume:.035,endFrequency:70});break;case'boil':note(440,0,.25,{type:'triangle',volume:.05,endFrequency:660});note(660,.08,.3,{type:'sine',volume:.045,endFrequency:990});note(880,.16,.4,{type:'triangle',volume:.035,endFrequency:1320});break;case'launch':note(180,0,.1,{type:'triangle',volume:.05,endFrequency:300});note(300,.07,.14,{type:'sine',volume:.04,endFrequency:420});break;case'target':note(410,0,.12,{type:'sine',volume:.055,endFrequency:560});if(chain>1)note(560,.08,.14,{type:'triangle',volume:.04,endFrequency:760});break;case'ring':note(480,0,.12,{type:'sine',volume:.045,endFrequency:720});note(720,.07,.18,{type:'triangle',volume:.035,endFrequency:980});break;case'switch':note(260,0,.12,{type:'triangle',volume:.05,endFrequency:360});note(460,.1,.2,{type:'sine',volume:.04,endFrequency:620});break;case'bottle':note(440,0,.16,{type:'sine',volume:.05});note(660,.12,.18,{type:'triangle',volume:.045});note(880,.26,.26,{type:'sine',volume:.04});break;case'hazard':note(230,0,.22,{type:'sawtooth',volume:.05,endFrequency:100});break;case'lost':note(200,0,.18,{type:'triangle',volume:.04,endFrequency:120});break;case'complete':note(523,0,.16,{type:'sine',volume:.05});note(659,.12,.18,{type:'sine',volume:.045});note(784,.24,.2,{type:'triangle',volume:.04});note(1046,.38,.32,{type:'sine',volume:.035});break;case'fail':note(220,0,.2,{type:'triangle',volume:.05,endFrequency:150});note(165,.14,.32,{type:'sawtooth',volume:.035,endFrequency:90});break;case'toggle':note(480,0,.1,{type:'sine',volume:.045,endFrequency:640});break;default:note(420,0,.09,{type:'sine',volume:.05,endFrequency:260});}}
const MUSIC_PATTERNS={classic:[261.63,329.63,392,523.25,440,392,329.63,293.66],launch:[220,261.63,329.63,392,329.63,293.66,261.63,329.63]};
function scheduleMusicTone(context,frequency,when,length,volume,type='triangle'){const oscillator=context.createOscillator(),gain=context.createGain(),start=Math.max(when,context.currentTime+.01),end=start+length;oscillator.type=type;oscillator.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(volume,start+.08);gain.gain.exponentialRampToValueAtTime(.0001,end);oscillator.connect(gain).connect(musicGain);oscillator.start(start);oscillator.stop(end+.04);}
function scheduleMusicStep(){if(muted||!audio||!musicGain)return;const context=audio,pattern=MUSIC_PATTERNS[gameMode]||MUSIC_PATTERNS.launch,frequency=pattern[musicStep%pattern.length],when=context.currentTime+.035;scheduleMusicTone(context,frequency,when,.46,.022,'triangle');if(musicStep%4===0)scheduleMusicTone(context,frequency/2,when,.9,.012,'sine');if(musicStep%2===1)scheduleMusicTone(context,frequency*2,when+.2,.22,.009,'sine');musicStep++;}
function startMusic(){if(muted||musicTimer)return;const context=ensureAudio();if(!context)return;if(context.state==='suspended')context.resume().catch(()=>{});musicGain.gain.cancelScheduledValues(context.currentTime);musicGain.gain.setTargetAtTime(musicDucked?.025:.08,context.currentTime,.08);musicStep=0;scheduleMusicStep();musicTimer=window.setInterval(scheduleMusicStep,520);}
function stopMusic(){if(musicTimer){window.clearInterval(musicTimer);musicTimer=0;}if(audio&&musicGain){musicGain.gain.cancelScheduledValues(audio.currentTime);musicGain.gain.setTargetAtTime(0,audio.currentTime,.03);}}
function duckMusic(duck){musicDucked=duck;if(!audio||!musicGain||muted)return;musicGain.gain.cancelScheduledValues(audio.currentTime);musicGain.gain.setTargetAtTime(duck?.025:.08,audio.currentTime,.08);}
function tone(frequency=420,length=.09){playSfx('tone',{frequency,length});}
function vibrate(pattern){if(reduced||muted||!navigator.vibrate)return;try{navigator.vibrate(pattern);}catch{}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');toastUntil=performance.now()+1800;}
function modeModifier(){return MODES[world.mode]||MODES.fluid;}
function activeAbility(){return abilities.gravityUntil||abilities.freezeUntil;}
function maxDanger(){return Math.max(0,...world.bodies.map(b=>b.danger));}
function invalidateCalmMission(danger){if(!mission||mission.kind!=='稳住果池'||mission.done||mission.failed||danger<=0)return;mission.failed=true;toast('果池进入危险，稳住果池委托已失效。');}

function syncUI(){
  if(gameMode==='launch'){syncLaunchUI();return;}
  const danger=maxDanger();dangerLevel=danger>=2?2:danger>=1?1:0;invalidateCalmMission(danger);
  $('score').textContent=score;$('best').textContent=best;$('energy').value=energy;$('energy-value').textContent=Math.floor(energy);
  $('heat').value=heat;$('heat-value').textContent=heatUntil?`沸腾 · ${Math.ceil(Math.max(0,heatUntil-world.time))} 秒`:`${Math.floor(heat)} / 100`;$('heat-row').classList.toggle('hot',Boolean(heatUntil));
  $('stir').disabled=energy<30||ended||paused;
  const abilityActive=Boolean(activeAbility());$('lab-charge').textContent=`${abilities.charge} / 3`;$('gravity-button').disabled=abilities.charge<3||abilityActive||ended||paused;$('freeze-button').disabled=abilities.charge<3||abilityActive||ended||paused;
  $('gravity-status').textContent=abilities.gravityUntil?`${Math.ceil(Math.max(0,abilities.gravityUntil-world.time))} 秒`:(abilityActive?'不可用':abilities.charge>=3?'可使用':'充能中');$('freeze-status').textContent=abilities.freezeUntil?(freezeDropUsed?'已投放':`${Math.ceil(Math.max(0,abilities.freezeUntil-world.time))} 秒`):(abilityActive?'不可用':abilities.charge>=3?'可使用':'充能中');
  $('vent').hidden=!(dangerLevel>0&&rescueAvailable&&!ended);$('vent').disabled=energy<40||paused;$('vent').querySelector('small').textContent=energy<40?'能量不足（需要 40）':paused?'暂停中':'消耗 40 能量 · 本局一次';
  $('game').dataset.fruits=world.bodies.length;$('game').dataset.phase=ended?'ended':paused?'paused':'playing';$('game').dataset.danger=dangerLevel;renderMission();
}
function showDialog(title,body,button,action,closable=true){paused=true;keys.clear();heldTilt=0;duckMusic(true);$('dialog-title').textContent=title;$('dialog-body').innerHTML=body;$('dialog-action').textContent=button;$('dialog-action').onclick=()=>{dialog.close();action();};$('dialog-close').hidden=!closable;if(!dialog.open)dialog.showModal();syncUI();}
function resume(){paused=false;duckMusic(false);if(!muted)unlockAudio();$('pause').querySelector('span').textContent='暂停';$('pause').setAttribute('aria-label','暂停');syncUI();}
function updateCodexRoute(){document.querySelectorAll('.fruit-step[data-fruit]').forEach(step=>step.classList.toggle('discovered',Boolean(codex.discovered[Number(step.dataset.fruit)])));}
function drawSprite(target,type,size=64,alpha=1){if(!target||!sprites[type])return;const context=target.getContext('2d');target.width=size*2;target.height=size*2;context.clearRect(0,0,target.width,target.height);context.globalAlpha=alpha;context.drawImage(sprites[type],4,4,target.width-8,target.height-8);context.globalAlpha=1;}
function discoverFruit(type){if(type<0||type>=TYPES.length||codex.discovered[type])return;codex.discovered[type]=true;saveCodex();updateCodexRoute();if(loaded)toast(`发现新水果：${TYPES[type].name}`);}
function refreshCodexSprites(){const grid=$('codex-grid');if(!grid)return;grid.querySelectorAll('.codex-card').forEach((card,index)=>drawSprite(card.querySelector('canvas'),index,54,codex.discovered[index]?1:.28));}
function openCodex(){const discovered=codex.discovered.filter(Boolean).length;showDialog('水果图鉴',`<p class="codex-summary">已发现 ${discovered} / ${TYPES.length} 种水果。合成新的水果即可解锁图鉴。</p><div class="codex-grid" id="codex-grid"></div>`,'继续实验',resume);const grid=$('codex-grid');TYPES.forEach((fruit,index)=>{const card=document.createElement('article'),known=Boolean(codex.discovered[index]);card.className=`codex-card${known?'':' locked'}`;const source=index>0?`${TYPES[index-1].name} + ${TYPES[index-1].name}`:'基础样本',next=index<TYPES.length-1?TYPES[index+1].name:'最高等级';card.innerHTML=`<canvas width="128" height="128" aria-hidden="true"></canvas><strong>${fruit.name}</strong><small>等级 ${index+1} · ${known?`来源：${source} · 下一阶：${next}`:`来源：${source} · 尚未合成`}</small>`;grid.append(card);});refreshCodexSprites();}

function saveBest(){if(score<=best)return;best=score;try{localStorage.setItem('melon-lab-best',String(best));}catch{}}
function highestName(){return runStats.merges?TYPES[Math.min(8,runStats.maxFruitType)]?.name||'葡萄':'尚未合成';}
function finishClassic(){if(ended)return;ended=true;const gap=score>runBest?'刷新了最佳分数！':`距离最佳分数还差 ${runBest-score} 分`;showDialog('果池满了，休息一下',`<div class="result-grid"><span>本局分数<strong>${score}</strong></span><span>最高水果<strong>${highestName()}</strong></span><span>最大连融<strong>${runStats.maxCombo}</strong></span><span>完成委托<strong>${runStats.missionsCompleted}</strong></span><span>沸腾次数<strong>${runStats.heatBursts}</strong></span></div><p>${gap}</p>`,'再来一池',resetClassic,false);}
function addHeat(event){if(heatUntil)return;heat=Math.min(100,heat+8+(event.perfect?4:0)+(event.cascade?8:0)+(combo>=3?4:0));if(heat<100)return;heat=0;heatUntil=world.time+5;heatBursts++;runStats.heatBursts++;toast('实验沸腾！融合得分 ×1.25');playSfx('boil');vibrate([18,30,18]);}

const world=new World(event=>{
  if(gameMode!=='classic')return;const mode=modeModifier(),within=world.time-lastMerge<=mode.comboWindow;combo=within?combo+1:1;lastMerge=world.time;const base=event.points,quality=Math.floor(base*Math.min(combo,4)),perfect=event.perfect?Math.ceil(base*.25):0,cascade=event.cascade?Math.ceil(base*.5):0;const heatMultiplier=heatUntil?1.25:1,delta=Math.max(1,Math.floor((quality+perfect+cascade)*mode.scoreMultiplier*heatMultiplier));score+=delta;energy=Math.min(100,energy+8);runStats.merges++;runStats.maxCombo=Math.max(runStats.maxCombo,combo);runStats.maxFruitType=Math.max(runStats.maxFruitType,event.type);if(event.cascade)runStats.cascadeCount++;if(event.variant)runStats.variantMerges++;addHeat(event);saveBest();effects.push({x:event.x,y:event.y,text:`+${delta}${combo>1?' · '+combo+' 连融':''}${event.cascade?' · 级联':''}${event.variant?' · '+VARIANTS[event.variant].label:''}`,life:event.cascade?1.5:1.2});ripples.push({x:event.x,y:event.y,life:.6,r:TYPES[event.type].r,color:event.variant?VARIANTS[event.variant].color:TYPES[event.type].color});playSfx('merge',{type:event.type,chain:combo,cascade:event.cascade,perfect:event.perfect});vibrate(event.cascade?[18,25,18]:event.perfect?12:6);const step=document.querySelector(`[data-fruit="${event.type}"]`);if(step){step.classList.remove('new');void step.offsetWidth;step.classList.add('new');}discoverFruit(event.type);updateMission({type:'merge',fruitType:event.type,mode:world.mode,combo});if(event.type===8&&!hasWon){hasWon=true;queueMicrotask(()=>{if(ended)return;showDialog('一颗会流动的大西瓜！',`<p>你把柔软的水果，融成了夏天。</p><strong>${score}</strong><p>最大连融 ${runStats.maxCombo} · 继续合成两颗西瓜，可以释放大片空间。</p>`,'继续实验',resume);});}syncUI();
});

function pickFruit(allowVariant=false){const roll=rng();let type=roll<.49?0:roll<.79?1:roll<.95?2:3;if(type===lastPicked)pickStreak++;else pickStreak=1;if(pickStreak>=4){type=(type+1+Math.floor(rng()*3))%4;pickStreak=1;}lastPicked=type;let variant=null;if(allowVariant&&rng()<.18){const rollVariant=rng();variant=rollVariant<1/3?'foam':rollVariant<2/3?'sticky':'burst';}return {type,variant};}
function makeMissionPool(){const target=1+Math.floor(rng()*2),mode=['jelly','fluid','juice'][Math.floor(rng()*3)],sourceName=TYPES[target].name,resultName=TYPES[target+1].name;return [{id:`fruit-${seed}-${target}`,kind:'合成目标',text:`用两个${sourceName}合成一个${resultName}${resultName==='柑橘'?'（橙色水果）':''}`,sourceType:target,targetType:target+1,target:1,progress:0,check:e=>e.type==='merge'&&e.fruitType===target+1},{id:`mode-${seed}-${mode}`,kind:'物理实验',text:`在${mode==='jelly'?'果冻':mode==='fluid'?'半流体':'果汁'}模式完成 3 次融合`,target:3,progress:0,mode,check:e=>e.type==='merge'&&e.mode===mode},{id:`combo-${seed}`,kind:'连锁实验',text:'完成 2 次连续融合',target:2,progress:0,check:e=>e.type==='merge'&&e.combo>=2},{id:`calm-${seed}`,kind:'稳住果池',text:'完成 10 次投放且不进入危险状态',target:10,progress:0,failed:false,check:e=>e.type==='drop'&&!e.danger}];}
function createMissionOffers(){const pool=makeMissionPool(),first=Math.floor(rng()*pool.length),second=(first+1+Math.floor(rng()*(pool.length-1)))%pool.length;return [pool[first],pool[second]];}
function renderMission(){if(!mission)return;$('mission-kind').textContent=mission.done?'已完成':mission.failed?'已失效':'进行中';$('mission-text').textContent=mission.text;$('mission-progress').max=mission.target;$('mission-progress').value=Math.min(mission.progress,mission.target);$('mission-value').textContent=`${Math.min(mission.progress,mission.target)} / ${mission.target}`;const target=$('mission-target');if(target){const fruitMission=mission.kind==='合成目标';target.hidden=!fruitMission;if(fruitMission){drawSprite($('mission-target-canvas'),mission.targetType,34);$('mission-target-name').textContent=TYPES[mission.targetType].name;$('mission-recipe').textContent=`${TYPES[mission.sourceType].name} + ${TYPES[mission.sourceType].name} → ${TYPES[mission.targetType].name}`;}}const offers=$('mission-offers');offers.replaceChildren();for(const [index,offer]of missionOffers.entries()){const button=document.createElement('button');button.type='button';button.dataset.index=index;button.disabled=Boolean(offer.failed||(mission.progress||mission.done)&&!mission.failed);button.className=offer===mission?'selected':'';button.innerHTML=`<span>${offer.kind}</span><small>${offer.text}</small>`;offers.append(button);}}
function selectMission(index){const selected=missionOffers[index];if(!selected||selected.failed)return;const currentLocked=Boolean(mission&&!mission.failed&&(mission.progress>0||mission.done));if(currentLocked)return;mission=selected;renderMission();toast(`已选择：${mission.text}`);playSfx('toggle');}
function completeMission(){if(!mission||mission.done||mission.failed)return;mission.done=true;score+=100;energy=Math.min(100,energy+15);abilities.charge=Math.min(3,abilities.charge+1);runStats.missionsCompleted++;saveBest();toast('委托完成！实验瓶充能 +1');playSfx('mission');vibrate([12,35,12]);syncUI();if(missionTimer)clearTimeout(missionTimer);missionTimer=window.setTimeout(()=>{if(ended)return;missionOffers=createMissionOffers();mission=missionOffers[0];renderMission();toast('新的实验委托已到达。');},1400);}
function updateMission(event){if(!mission||mission.done||mission.failed||!mission.check(event))return;mission.progress++;if(mission.progress>=mission.target)completeMission();else syncUI();}
function resetClassic(){world.reset();world.setMode(document.querySelector('[data-mode][aria-pressed=true]')?.dataset.mode||'fluid');runBest=best;score=0;energy=100;cooldown=0;aim=250;ended=false;hasWon=false;paused=false;effects=[];ripples=[];combo=0;lastMerge=-Infinity;heat=0;heatUntil=0;heatBursts=0;seed=newSeed();rng=createRng(seed);lastPicked=-1;pickStreak=0;fruitQueue=[pickFruit(false),pickFruit(false),pickFruit(false)];abilities={charge:0,gravityUntil:0,freezeUntil:0};freezeDropUsed=false;rescueAvailable=true;dangerLevel=0;runStats={drops:0,merges:0,maxFruitType:0,maxCombo:0,cascadeCount:0,missionsCompleted:0,abilitiesUsed:0,variantDrops:0,variantMerges:0,heatBursts:0,modeUsage:{jelly:0,fluid:0,juice:0},seed};missionOffers=createMissionOffers();mission=missionOffers[0];if(missionTimer)clearTimeout(missionTimer);missionTimer=0;keys.clear();heldTilt=0;if(dialog.open)dialog.close();updateNext();resume();$('aim-tip').textContent='移动瞄准 · 点击投放';}
function dropClassic(){if(!loaded||paused||ended||world.time<cooldown)return;if(abilities.freezeUntil&&freezeDropUsed){toast('定型剂只能安排一颗新水果。');return;}const sample=fruitQueue[0],type=sample.type,r=TYPES[type].r;aim=Math.max(BOUNDS.left+r+3,Math.min(BOUNDS.right-r-3,aim));world.add(type,aim,65,world.tilt*20,70,{variant:sample.variant});if(abilities.freezeUntil)freezeDropUsed=true;fruitQueue.shift();runStats.drops++;if(sample.variant)runStats.variantDrops++;fruitQueue.push(pickFruit(runStats.drops>=8));runStats.modeUsage[world.mode]++;updateNext();cooldown=world.time+.42;playSfx('drop');updateMission({type:'drop',danger:maxDanger()});syncUI();}
function stir(){if(!loaded||paused||ended||energy<30)return;energy-=30;world.stir();ripples.push({x:250,y:430,life:1,r:130,color:'#9b85db'});playSfx('stir');toast('轻轻搅一搅，好事会相遇。');syncUI();}
function useGravity(){if(!loaded||paused||ended||abilities.charge<3||activeAbility())return;abilities.charge-=3;abilities.gravityUntil=world.time+8;world.gravityScale=.5;runStats.abilitiesUsed++;toast('减重剂生效，果池变轻了。');playSfx('ability');vibrate([14,40,14]);syncUI();}
function useFreeze(){if(!loaded||paused||ended||abilities.charge<3||activeAbility())return;abilities.charge-=3;abilities.freezeUntil=world.time+4;freezeDropUsed=false;world.freezeExisting(abilities.freezeUntil);runStats.abilitiesUsed++;toast('定型剂生效，安排好这一颗水果。');playSfx('ability');vibrate([14,40,14]);syncUI();}
function vent(){if(!loaded||paused||ended||!rescueAvailable||energy<40||dangerLevel===0)return;energy-=40;rescueAvailable=false;world.releaseVent();toast('紧急排气！果池重新落稳了。');playSfx('vent');vibrate([20,35,20]);syncUI();}
function updateNext(){if(!loaded)return;fruitQueue.forEach((sample,index)=>{const target=$(queueCanvasIds[index]),c=target.getContext('2d');c.clearRect(0,0,144,144);c.globalAlpha=index===0?.98:.72;c.drawImage(sprites[sample.type],8,8,128,128);if(sample.variant){c.globalAlpha=1;c.strokeStyle=VARIANTS[sample.variant].color;c.lineWidth=4;c.beginPath();c.arc(72,72,61,0,TAU);c.stroke();c.font='600 13px sans-serif';c.textAlign='center';c.fillStyle=VARIANTS[sample.variant].color;c.fillText(VARIANTS[sample.variant].label,72,18);}c.globalAlpha=1;target.setAttribute('aria-label',`${index===0?'当前':index===1?'下一颗':'之后'}水果：${TYPES[sample.type].name}${sample.variant?`，${VARIANTS[sample.variant].label}样本`:''}`);});}

function glassPath(){ctx.beginPath();ctx.moveTo(31,49);ctx.lineTo(19,49);ctx.quadraticCurveTo(14,49,14,59);ctx.lineTo(14,548);ctx.quadraticCurveTo(14,590,55,590);ctx.lineTo(445,590);ctx.quadraticCurveTo(486,590,486,548);ctx.lineTo(486,59);ctx.quadraticCurveTo(486,49,469,49);}
function drawGlass(front=false){if(!front){const fill=ctx.createLinearGradient(0,70,0,588);fill.addColorStop(0,'#ffffff08');fill.addColorStop(.85,'#d5c9ff09');fill.addColorStop(1,'#b2a0db30');ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(20,50,460,534,[4,4,34,34]);ctx.fill();return;}ctx.save();glassPath();ctx.lineJoin='round';ctx.lineCap='round';ctx.shadowBlur=9;ctx.shadowColor='#80719b2d';ctx.shadowOffsetY=6;ctx.strokeStyle='#b1a6d6';ctx.lineWidth=10;ctx.stroke();ctx.shadowBlur=0;ctx.shadowOffsetY=0;ctx.strokeStyle='#ece8ff';ctx.lineWidth=6.5;ctx.stroke();ctx.strokeStyle='#ffffffc9';ctx.lineWidth=2;ctx.stroke();ctx.restore();ctx.save();ctx.font='9px "Avenir Next",sans-serif';ctx.textAlign='left';ctx.fillStyle='#a297b8';ctx.lineWidth=1;ctx.strokeStyle='#b9abd180';for(let y=170;y<560;y+=50){ctx.beginPath();ctx.moveTo(29,y);ctx.lineTo(35,y);ctx.stroke();ctx.fillText(String(600-y),38,y+3);}ctx.restore();}
function pathBody(body){const p=body.p;ctx.beginPath();ctx.moveTo((p[N-1].x+p[0].x)/2,(p[N-1].y+p[0].y)/2);for(let i=0;i<N;i++){const q=p[(i+1)%N];ctx.quadraticCurveTo(p[i].x,p[i].y,(p[i].x+q.x)/2,(p[i].y+q.y)/2);}ctx.closePath();}
function triangle(image,source,dest){const [s0,s1,s2]=source,[d0,d1,d2]=dest,sx1=s1.x-s0.x,sy1=s1.y-s0.y,sx2=s2.x-s0.x,sy2=s2.y-s0.y,det=sx1*sy2-sx2*sy1;if(Math.abs(det)<.001)return;const dx1=d1.x-d0.x,dy1=d1.y-d0.y,dx2=d2.x-d0.x,dy2=d2.y-d0.y,a=(dx1*sy2-dx2*sy1)/det,b=(dy1*sy2-dy2*sy1)/det,c=(dx2*sx1-dx1*sx2)/det,d=(dy2*sx1-dy1*sx2)/det;ctx.save();ctx.beginPath();for(let i=0;i<3;i++){const p=dest[i],x=p.x+(p.x-(d0.x+d1.x+d2.x)/3)*.012,y=p.y+(p.y-(d0.y+d1.y+d2.y)/3)*.012;if(i)ctx.lineTo(x,y);else ctx.moveTo(x,y);}ctx.closePath();ctx.clip();ctx.transform(a,b,c,d,d0.x-a*s0.x-c*s0.y,d0.y-b*s0.x-d*s0.y);ctx.drawImage(image,0,0);ctx.restore();}
const sourceRim=Array.from({length:N},(_,i)=>({x:128+Math.cos(TAU*i/N)*128,y:128+Math.sin(TAU*i/N)*128}));
function drawVariantRing(x,y,r,variant,alpha=1){const meta=VARIANTS[variant];if(!meta)return;ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle=meta.color;ctx.lineWidth=2.5;ctx.setLineDash([4,4]);ctx.beginPath();ctx.arc(x,y,r+4,0,TAU);ctx.stroke();ctx.setLineDash([]);ctx.font='600 10px sans-serif';ctx.textAlign='center';ctx.fillStyle=meta.color;ctx.fillText(meta.label,x,y-r-8);ctx.restore();}
function drawBody(body){ctx.save();pathBody(body);ctx.shadowColor=TYPES[body.type].color+'40';ctx.shadowBlur=9;ctx.shadowOffsetY=3;ctx.fillStyle=TYPES[body.type].color+'42';ctx.fill();ctx.shadowBlur=0;ctx.shadowOffsetY=0;ctx.clip();for(let i=0;i<N;i++)triangle(sprites[body.type],[{x:128,y:128},sourceRim[i],sourceRim[(i+1)%N]],[{x:body.x,y:body.y},body.p[i],body.p[(i+1)%N]]);ctx.restore();if(body.variant&&(body.variant==='burst'||body.variantUntil>world.time))drawVariantRing(body.x,body.y,body.r,body.variant,.9);}
function renderClassic(){ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);ctx.clearRect(0,0,W,H);drawGlass();const danger=maxDanger();ctx.save();ctx.setLineDash([8,8]);ctx.lineCap='round';ctx.strokeStyle=danger>=2?'#d94e6c':danger>=1?'#e77a8d':'#ff8b98';ctx.lineWidth=danger>=1?2.5:1.8;ctx.beginPath();ctx.moveTo(26,BOUNDS.line);ctx.lineTo(474,BOUNDS.line);ctx.stroke();ctx.restore();if(loaded){for(const body of world.bodies)drawBody(body);if(!paused&&!ended){const sample=fruitQueue[0],r=TYPES[sample.type].r,x=Math.max(BOUNDS.left+r+3,Math.min(BOUNDS.right-r-3,aim));ctx.save();ctx.setLineDash([4,8]);ctx.strokeStyle='#a99ac780';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(x,65+r+10);ctx.lineTo(x,570);ctx.stroke();ctx.globalAlpha=world.time<cooldown?.3:.85;ctx.drawImage(sprites[sample.type],x-r,65-r,r*2,r*2);ctx.restore();if(sample.variant)drawVariantRing(x,65,r,sample.variant,.75);}}drawGlass(true);for(const e of ripples){ctx.save();ctx.strokeStyle=e.color;ctx.globalAlpha=e.life*.3;ctx.lineWidth=1.3;ctx.beginPath();ctx.ellipse(e.x,e.y,e.r*(2-e.life),e.r*(2-e.life)*.65,0,0,TAU);ctx.stroke();ctx.restore();}for(const e of effects){ctx.save();ctx.globalAlpha=Math.min(1,e.life*2);ctx.font='600 21px "Avenir Next","PingFang SC",sans-serif';ctx.textAlign='center';ctx.fillStyle='#7563af';ctx.strokeStyle='#f7f3ff';ctx.lineWidth=4;ctx.strokeText(e.text,e.x,e.y);ctx.fillText(e.text,e.x,e.y);ctx.restore();}if(danger>0){ctx.save();ctx.font='600 13px "PingFang SC",sans-serif';ctx.textAlign='center';ctx.fillStyle=danger>=2?'#c94f69':'#d95970';ctx.fillText(`注意高度 · ${Math.max(1,Math.ceil(3-danger))} 秒`,250,104);ctx.restore();}}

function goalLabel(goal){const target=launchLevel?.targets?.find(item=>item.id===goal.targetId);const name=target?.kind==='ring'?'穿过':target?.kind==='switch'?'触发':target?.kind==='bottle'?'送入':'点亮';const targetName=target?.kind==='ring'?'实验环':target?.kind==='switch'?'机关':target?.kind==='bottle'?'成品瓶':'实验晶体';const fruit=goal.requiredType!=null?` · ${TYPES[goal.requiredType].name}`:'';return `${name}${targetName}${fruit} ${Math.min(goal.progress,goal.count)} / ${goal.count}`;}
function renderLaunchGoals(){const list=$('launch-goals');if(!list)return;list.replaceChildren();for(const goal of launchState.goals){const item=document.createElement('div');item.className=`launch-goal${goal.done?' done':''}`;item.innerHTML=`<span class="goal-mark">${goal.done?'✓':'○'}</span><span>${goalLabel(goal)}</span>`;list.append(item);}$('launch-goal-count').textContent=`${launchState.completedGoals} / ${launchState.goals.length}`;}
function updateLaunchAimReadout(){const readout=$('launch-aim-readout');if(!readout)return;const force=Math.round(Math.min(100,Math.max(0,launchState.aim.force||0)));const angle=Number.isFinite(launchState.aim.angle)?Math.round(launchState.aim.angle):0;$('launch-force').textContent=`${force}%`;$('launch-angle').textContent=`${angle}°`;const sample=launchState.fruitQueue[0]?.type??0,target=launchWorld.targets.find(item=>item.id===launchAimReadout.nearestTarget),hitDistance=(target?.r||18)+(TYPES[sample]?.r||18)+8,likelyHit=Boolean(target&&launchAimReadout.nearestDistance<hitDistance),typeMismatch=Boolean(target&&target.requiredType!=null&&target.requiredType!==sample);const warning=launchState.aim.warning==='danger'?'路线会经过危险区':typeMismatch?'水果类型不匹配':likelyHit?'可能命中目标':launchState.shotState==='aiming'?'继续微调路线':'等待瞄准';$('launch-aim-warning').textContent=warning;readout.classList.toggle('warning',launchState.aim.warning==='danger'||typeMismatch);readout.classList.toggle('good',Boolean(likelyHit&&!typeMismatch&&launchState.aim.warning!=='danger'));}
function renderLaunchRecord(){const key=launchKey(launchState.levelId),record=launchProgress.ghosts?.[key],valid=record&&Array.isArray(record.shots)&&record.shots.length>0,text=$('launch-record-text'),button=$('launch-ghost');if(!text||!button)return;if(valid){text.textContent=`${Number(record.score)||0} 分 · ${record.shots.length} 发 · ${record.rating||'C'} 级`;button.disabled=false;button.textContent=launchState.ghost.playing?'停止最佳路线':'查看最佳路线';}else{text.textContent='尚无最佳路线';button.disabled=true;button.textContent='查看最佳路线';}}
function syncLaunchUI(){if(gameMode!=='launch')return;$('launch-score').textContent=launchState.score;$('launch-best').textContent=launchState.best;$('launch-level-title').textContent=launchLevel.title;$('launch-level-desc').textContent=launchLevel.description;$('launch-level-number').textContent=launchState.levelId==='seeded'?'★':launchState.levelId;$('launch-stability').value=launchState.stability;$('launch-stability-value').textContent=Math.max(0,Math.ceil(launchState.stability));$('launch-combo').textContent=launchState.combo;$('launch-max-combo').textContent=launchState.maxCombo;const stabilityTip=launchState.stability<=10?'即将失败 · 小心危险区域。':launchState.stability<=25?'实验不稳定 · 还可以挽回。':launchState.stability<=50?'注意稳定度 · 避开错误目标。':null;const status=launchState.ended?(launchState.rating?'实验完成':'实验失败'):stabilityTip||(launchState.shotState==='aiming'?'调整方向，松手发射。':launchState.shotState==='flying'?'观察水果的路线。':launchState.failure.reason?`上次结果：${launchState.failure.reason}`:launchState.ammo?`剩余样本 ${launchState.ammo} 颗 · 拖拽底部水果瞄准。`:'样本耗尽，完成最后一次结算。');$('launch-status').textContent=status;renderLaunchGoals();renderLaunchLevels();updateLaunchAimReadout();renderLaunchRecord();}
function renderLaunchLevels(){const list=$('launch-level-list');if(!list)return;list.replaceChildren();for(const level of LAUNCH_LEVELS){const button=document.createElement('button');button.type='button';button.dataset.level=level.id;button.disabled=level.id>launchProgress.unlockedLevel;button.className=String(level.id)===String(launchState.levelId)?'selected':'';button.innerHTML=`<b>${level.id}</b><span>${level.title}</span><small>${launchProgress.bestRatings[level.id]||'—'}</small>`;list.append(button);}}
function pickLaunchFruit(){const pool=launchLevel.recommendedTypes?.length?launchLevel.recommendedTypes:Array.from({length:4},(_,i)=>i);return {type:pool[Math.floor(launchRng()*pool.length)],variant:null};}
function getLaunchLevel(id){return id==='seeded'?LAUNCH_CHALLENGE.template:LAUNCH_LEVELS.find(level=>level.id===Number(id))||LAUNCH_LEVELS[0];}
function launchKey(id){return String(id);}
function calculateLaunchRating(scoreValue){const thresholds=launchLevel.scoreThresholds||{B:240,A:420,S:620};return scoreValue>=thresholds.S?'S':scoreValue>=thresholds.A?'A':scoreValue>=thresholds.B?'B':'C';}
function saveLaunchResult(){const key=launchKey(launchState.levelId),current=Number(launchProgress.bestScores[key]||0);if(launchState.score>current)launchProgress.bestScores[key]=launchState.score;const rating=launchState.rating,rank={C:1,B:2,A:3,S:4};if(rating&&(!launchProgress.bestRatings[key]||rank[rating]>rank[launchProgress.bestRatings[key]]))launchProgress.bestRatings[key]=rating;const previousShots=Number(launchProgress.bestShots[key]||Infinity),previousStability=Number(launchProgress.bestStability[key]||0);if(launchState.shotHistory.length<previousShots||launchState.score>current){launchProgress.bestShots[key]=launchState.shotHistory.length;launchProgress.ghosts[key]={levelId:launchState.levelId,seed:launchState.seed,fruitTypes:launchState.ghost.current.map(shot=>shot.type),shots:launchState.ghost.current.slice(0,launchLevel.ammo+1),score:launchState.score,rating:launchState.rating,stability:launchState.stability};}if(launchState.stability>previousStability)launchProgress.bestStability[key]=launchState.stability;if(launchState.levelId!=='seeded'&&Number(launchState.levelId)>=launchProgress.unlockedLevel)launchProgress.unlockedLevel=Math.min(LAUNCH_LEVELS.length,Number(launchState.levelId)+1);launchProgress.completed[key]=true;saveLaunchProgress();}
function launchEffect(x,y,text,color='#7563af'){launchEffects.push({x,y,text,color,life:1.25});}
function reduceLaunchStability(amount,reason){const before=launchState.stability;launchState.stability=Math.max(0,launchState.stability-amount);if(before>50&&launchState.stability<=50)launchEffect(W/2,92,'实验台开始晃动','#c88b55');if(before>25&&launchState.stability<=25)launchEffect(W/2,116,'实验不稳定','#d47773');if(before>10&&launchState.stability<=10)launchEffect(W/2,140,'即将失败','#d45f7c');if(launchState.stability<=0){failLaunch(reason||'实验台失稳');return false;}return true;}
function updateLaunchGoal(event){if(event.special==='wrong-type')return;for(const goal of launchState.goals){if(goal.done||goal.kind!==({'target-hit':'hit','ring-pass':'ring','switch-activate':'switch','bottle-fill':'bottle'}[event.type]))continue;if(goal.targetId&&goal.targetId!==event.targetId)continue;if(goal.requiredType!=null&&goal.requiredType!==event.fruitType)continue;goal.progress=Math.min(goal.count,goal.progress+1);if(goal.progress>=goal.count)goal.done=true;}launchState.completedGoals=launchState.goals.filter(goal=>goal.done).length;if(launchState.completedGoals===launchState.goals.length)launchState.pendingComplete=true;}
function finishLaunchLevel(){if(launchState.ended)return;launchState.score+=launchState.ammo*25;launchState.best=Math.max(launchState.best,launchState.score);launchState.rating=calculateLaunchRating(launchState.score);launchState.ended=true;launchState.shotState='complete';ended=true;launchWorld.projectile=null;saveLaunchResult();const next=launchState.levelId==='seeded'?null:Number(launchState.levelId)<LAUNCH_LEVELS.length?Number(launchState.levelId)+1:null;const record=launchProgress.ghosts?.[launchKey(launchState.levelId)],recordShots=Array.isArray(record?.shots)?record.shots.length:launchState.shotHistory.length;const button=next?'下一关':'再玩一次';const action=next?()=>loadLaunchLevel(next):()=>loadLaunchLevel(launchState.levelId);playSfx('complete');showDialog('实验完成！',`<div class="result-grid"><span>本关得分<strong>${launchState.score}</strong></span><span>完成目标<strong>${launchState.completedGoals}/${launchState.goals.length}</strong></span><span>最大连锁<strong>${launchState.maxCombo}</strong></span><span>剩余样本<strong>${launchState.ammo}</strong></span><span>实验评级<strong>${launchState.rating}</strong></span><span>最佳发射<strong>${recordShots} 发</strong></span></div><p>${launchLevel.title} 已完成，${record?'最佳路线已保存。':'可以再试一次，寻找更短路线。'}</p>`,button,action,false);}
function failLaunch(reason='实验台失稳'){if(launchState.ended)return;launchState.ended=true;launchState.shotState='failed';launchState.failure.reason=reason;ended=true;launchWorld.projectile=null;launchEffect(W/2,250,reason,'#d45f7c');playSfx('fail');showDialog('实验需要重来',`<p>${reason}</p><div class="result-grid"><span>本关得分<strong>${launchState.score}</strong></span><span>已完成目标<strong>${launchState.completedGoals}/${launchState.goals.length}</strong></span><span>剩余样本<strong>${launchState.ammo}</strong></span><span>稳定度<strong>${Math.max(0,Math.ceil(launchState.stability))}</strong></span></div><p>${launchLevel.hint}</p>`,'再试一次',()=>loadLaunchLevel(launchState.levelId),false);}
function launchFailureReason(reason){return ({lost:'样本进入废料槽或飞行超时',settled:'本次发射没有命中目标',bottle:'已进入成品瓶',hazard:'水果进入危险区域',wrong:'水果类型与目标不匹配'}[reason]||reason||'实验没有命中目标');}
function showLaunchShotSummary(){const box=$('launch-shot-summary');if(!box)return;const shot=launchState.lastShot,targets=shot.targets.length?`命中 ${shot.targets.length} 个目标`:'未命中目标',chain=shot.chain>1?` · ${shot.chain} 连锁`:'';box.innerHTML=`<strong>${targets}${chain}</strong><br><span>本发射 +${shot.score} 分${shot.perfect?' · 完美路线':''}${shot.hazards?' · 危险 -'+shot.hazards:''}</span>`;box.hidden=false;window.clearTimeout(showLaunchShotSummary.timer);showLaunchShotSummary.timer=window.setTimeout(()=>{box.hidden=true;},reduced?900:1700);}
