function frame(now){
  const dt=Math.min((now-last)/1000||0,.065);
  last=now;
  if(loaded&&!paused&&!ended&&!document.hidden){
    accumulator+=dt;
    if(gameMode==='classic'){
      world.tilt=heldTilt+(keys.has('a')?-1:0)+(keys.has('d')?1:0);
      if(keys.has('arrowleft'))aim-=250*dt;
      if(keys.has('arrowright'))aim+=250*dt;
      aim=Math.max(45,Math.min(455,aim));
      while(accumulator>=1/120){world.step(1/120);accumulator-=1/120;}
      if(abilities.gravityUntil&&world.time>=abilities.gravityUntil){abilities.gravityUntil=0;world.gravityScale=1;toast('减重剂结束，重力恢复。');}
      if(abilities.freezeUntil&&world.time>=abilities.freezeUntil){abilities.freezeUntil=0;freezeDropUsed=false;toast('定型剂结束，水果重新流动。');}
      if(heatUntil&&world.time>=heatUntil){heatUntil=0;toast('沸腾结束，继续积累热度。');}
      if(!heatUntil)heat=Math.max(0,heat-dt*8);
      energy=Math.min(100,energy+dt*2.3);
      for(const e of effects){e.life-=dt;e.y-=dt*27;}
      effects=effects.filter(e=>e.life>0);
      for(const e of ripples)e.life-=dt;
      ripples=ripples.filter(e=>e.life>0);
      if(maxDanger()>=3)finishClassic();
    }else{
      while(accumulator>=1/120){launchWorld.step(1/120);accumulator-=1/120;}
      for(const e of launchEffects){e.life-=dt;e.y-=dt*23;}
      launchEffects=launchEffects.filter(e=>e.life>0);
      for(const e of launchRipples)e.life-=dt;
      launchRipples=launchRipples.filter(e=>e.life>0);
    }
  }else accumulator=0;
  uiClock+=dt;
  if(uiClock>.1){uiClock=0;syncUI();}
  if(now>toastUntil)$('toast').classList.remove('visible');
  render();
  requestAnimationFrame(frame);
}

function classicPointAim(event){const rect=canvas.getBoundingClientRect(),contentWidth=Math.min(rect.width,rect.height*W/H),left=rect.left+(rect.width-contentWidth)/2;aim=(event.clientX-left)*W/contentWidth;}
function launchPointerDown(event){if(!loaded||gameMode!=='launch'||paused||ended||launchState.shotState!=='ready'||event.isPrimary===false)return;const point=launchPoint(event),origin={x:launchWorld.launcherX,y:launchLevel.launcher?.y||548};if(point.y<origin.y-35)return;launchPointer=event.pointerId;try{canvas.setPointerCapture(event.pointerId);}catch{}canvas.classList.add('pointer-focused');updateLaunchAim(point);event.preventDefault();}
function launchPointerMove(event){if(launchPointer!==event.pointerId)return;updateLaunchAim(launchPoint(event));event.preventDefault();}
function launchPointerUp(event){if(launchPointer!==event.pointerId)return;updateLaunchAim(launchPoint(event));launchPointer=null;try{canvas.releasePointerCapture?.(event.pointerId);}catch{}launchFire();event.preventDefault();}
function launchPointerCancel(){launchPointer=null;launchState.aim={active:false,pointerId:null,angle:0,force:0,velocity:{x:0,y:0},predictedPoint:null,warning:null};launchAimReadout={points:[],nearestTarget:null,nearestDistance:Infinity,warning:null,landingPoint:null};if(launchState.shotState==='aiming'){launchState.shotState='ready';syncLaunchUI();}}
let classicPointer=null;
canvas.addEventListener('pointerdown',event=>{if(gameMode==='launch'){launchPointerDown(event);return;}if(!loaded||paused||ended||classicPointer!==null)return;classicPointer=event.pointerId;try{canvas.setPointerCapture(event.pointerId);}catch{}canvas.classList.add('pointer-focused');canvas.focus({preventScroll:true});classicPointAim(event);event.preventDefault();});
canvas.addEventListener('pointermove',event=>{if(gameMode==='launch'){launchPointerMove(event);return;}if(event.pointerType==='mouse'||classicPointer===event.pointerId)classicPointAim(event);});
canvas.addEventListener('pointerup',event=>{if(gameMode==='launch'){launchPointerUp(event);return;}if(classicPointer!==event.pointerId)return;classicPointAim(event);classicPointer=null;dropClassic();});
canvas.addEventListener('pointercancel',()=>{if(gameMode==='launch')launchPointerCancel();else classicPointer=null;});
for(const[id,direction]of[['tilt-left',-1],['tilt-right',1]]){const button=$(id);button.addEventListener('pointerdown',event=>{if(gameMode!=='classic')return;event.preventDefault();button.setPointerCapture(event.pointerId);heldTilt=direction;});for(const name of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(name,()=>heldTilt=0);}
document.addEventListener('keydown',event=>{if(dialog.open)return;const key=event.key.toLowerCase();if(gameMode==='launch'){if(key==='r'&&!event.repeat){loadLaunchLevel(launchState.levelId);return;}if(key==='arrowleft'||key==='arrowright'){event.preventDefault();launchWorld.setLauncher(launchWorld.launcherX+(key==='arrowleft'?-18:18));if(launchState.shotState==='aiming'){launchAim.vx+=(key==='arrowleft'?-45:45);refreshLaunchAim();}syncLaunchUI();return;}if((key===' '||key==='enter')&&!event.repeat){event.preventDefault();if(launchState.shotState==='ready'){launchAim={vx:0,vy:-560};refreshLaunchAim();launchState.shotState='aiming';}launchFire();}return;}canvas.classList.remove('pointer-focused');if(['arrowleft','arrowright','a','d'].includes(key)){event.preventDefault();keys.add(key);}if((key===' '||key==='enter')&&!event.repeat&&!['BUTTON','A'].includes(document.activeElement.tagName)){event.preventDefault();key===' '?stir():dropClassic();}if(key==='v'&&!event.repeat)vent();if(key==='p'&&!event.repeat)$('pause').click();});
document.addEventListener('keyup',event=>keys.delete(event.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();heldTilt=0;classicPointer=null;duckMusic(true);if(gameMode==='launch'){launchPointerCancel();}});window.addEventListener('focus',()=>{duckMusic(paused);if(!muted&&!paused)unlockAudio();});document.addEventListener('visibilitychange',()=>{keys.clear();heldTilt=0;last=performance.now();duckMusic(document.hidden||paused);if(!document.hidden&&!muted&&!paused)unlockAudio();if(document.hidden&&gameMode==='launch'&&launchState.shotState==='aiming')launchPointerCancel();});

document.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{if(gameMode!=='classic')return;world.setMode(button.dataset.mode);document.querySelectorAll('[data-mode]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));$('mode-desc').textContent=MODES[world.mode].label;playSfx('toggle');syncUI();}));
$('mission-offers').addEventListener('click',event=>{const button=event.target.closest('button[data-index]');if(button)selectMission(Number(button.dataset.index));});$('stir').addEventListener('click',stir);$('gravity-button').addEventListener('click',useGravity);$('freeze-button').addEventListener('click',useFreeze);$('vent').addEventListener('click',vent);$('codex').addEventListener('click',openCodex);$('play-classic').addEventListener('click',()=>requestGameMode('classic'));$('play-launch').addEventListener('click',()=>requestGameMode('launch'));
$('launch-retry').addEventListener('click',()=>{if(gameMode==='launch')loadLaunchLevel(launchState.levelId);});$('launch-levels').addEventListener('click',()=>{$('launch-level-list').hidden=!$('launch-level-list').hidden;syncLaunchUI();});$('launch-level-list').addEventListener('click',event=>{const button=event.target.closest('button[data-level]');if(!button||button.disabled)return;const id=Number(button.dataset.level);if(launchState.score>0||launchState.shotState!=='ready')showDialog('切换关卡？','当前实验进度会清零。','切换',()=>loadLaunchLevel(id));else loadLaunchLevel(id);});$('launch-challenge').addEventListener('click',()=>{if(launchState.score>0||launchState.shotState!=='ready')showDialog('进入种子挑战？','当前实验进度会清零。','进入挑战',()=>loadLaunchLevel('seeded',LAUNCH_CHALLENGE.seed));else loadLaunchLevel('seeded',LAUNCH_CHALLENGE.seed);});
