$('sound').addEventListener('click',()=>{muted=!muted;try{localStorage.setItem(SOUND_KEY,muted?'off':'on');}catch{}syncSoundUI();if(muted)stopMusic();else{unlockAudio();playSfx('toggle');}});$('pause').addEventListener('click',()=>{if(ended)return;showDialog(gameMode==='launch'?'让实验台歇一会儿':'让果冻歇一会儿',gameMode==='launch'?'水果和机关都停在这里。':'水果和时间都停在这里。','继续游戏',resume);});$('restart').addEventListener('click',()=>{if(gameMode==='launch'){if(launchState.score>0||launchState.shotState!=='ready')showDialog('重试当前实验？','本关进度会清零，最佳纪录会保留。','重新开始',()=>loadLaunchLevel(launchState.levelId));else loadLaunchLevel(launchState.levelId);return;}if(score===0){resetClassic();return;}showDialog('开始一池新的水果？','本局分数将清零，最佳分数会保留。','重新开始',resetClassic);});
syncSoundUI();document.addEventListener('pointerdown',()=>{if(!muted)unlockAudio();},{passive:true});document.addEventListener('keydown',()=>{if(!muted)unlockAudio();},{passive:true});
 $('help').addEventListener('click',()=>showDialog(gameMode==='launch'?'水果弹射实验':'一点物理，一点好运',gameMode==='launch'?'<p>按住底部水果向下拖拽，调整方向和力度，松手发射。</p><p>力度、角度和预测落点会实时显示；紫色高亮表示接近目标，红色表示路线经过危险区。</p><p>水果会反弹、穿过实验环、触发机关。一次发射完成多个目标，会获得连锁和完美路线奖励。</p><p>每关有有限样本。错误目标、危险区和废料槽会降低实验稳定度；首次完全未命中时，会回放一次路线并给出提示。</p><p>葡萄反弹更远，樱桃会吸附，柑橘有冲击波，柠檬可以沿导电轨道连锁。</p><p>电脑上可用鼠标拖拽，方向键移动发射台，空格发射，R 重试；完成关卡后可查看本地最佳路线。</p><p>开启声音后，会有轻柔循环音乐；命中、连锁和完成目标会使用不同音色反馈。点击声音按钮即可静音。</p>':'<p>移动鼠标瞄准，点击投放。手机上拖动瞄准，松手投放。</p><p>同类水果碰到一起就会融合。队列会显示当前和后面两颗水果。</p><p>切换「果冻 / 半流体 / 果汁」，感受不同弹性与策略优势。按 A / D 倾斜，按空格搅动。</p><p>完成实验委托可获得实验瓶充能。充满 3 格后可使用减重剂或定型剂。</p><p>第 11 次投放后，队列可能出现泡沫、黏胶或爆汁实验样本；观察它们的彩色标记，利用不同物理效果制造连锁。</p><p>连续融合会积累热度，热度满后自动进入 5 秒沸腾，融合得分提高。</p><p>水果稳定越过虚线会进入危险状态。按 V 或点击紧急排气，每局可以救场一次。</p><p>开启声音后，会有轻柔循环音乐；投放、融合、委托和沸腾都有不同音效。点击声音按钮即可静音。</p>','开始实验',resume));$('dialog-close').addEventListener('click',()=>{dialog.close();resume();});dialog.addEventListener('cancel',event=>{if(ended){event.preventDefault();return;}resume();});
function resize(){const ratio=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*ratio);canvas.height=Math.round(H*ratio);}resize();window.addEventListener('resize',resize);
const atlas=new Image();atlas.onload=()=>{const cell=atlas.width/3;for(let i=0;i<9;i++){const sprite=document.createElement('canvas');sprite.width=256;sprite.height=256;sprite.getContext('2d').drawImage(atlas,i%3*cell,Math.floor(i/3)*cell,cell,cell,0,0,256,256);sprites.push(sprite);const step=document.createElement('span');step.className='fruit-step';step.dataset.fruit=i;step.title=TYPES[i].name;const preview=document.createElement('canvas');preview.width=144;preview.height=144;preview.setAttribute('role','img');preview.setAttribute('aria-label',TYPES[i].name);preview.getContext('2d').drawImage(sprite,6,6,132,132);step.append(preview);step.insertAdjacentHTML('beforeend',`<small class="fruit-name">${TYPES[i].name}</small>`);if(i<8)step.insertAdjacentHTML('beforeend','<svg aria-hidden="true"><use href="#i-chevron"/></svg>');$('fruit-route').append(step);}updateCodexRoute();loaded=true;$('loading').hidden=true;applyModeLayout();if(gameMode==='launch')loadLaunchLevel(1);else resetClassic();};atlas.onerror=()=>{$('loading').textContent='水果素材加载失败，请刷新重试。';};atlas.src='fruits.png';
requestAnimationFrame(frame);
